use std::ops::Deref;
pub struct Window {
    window: Option<winit:🪟:Window>,
    pub title: &'static str,
}

impl Window {
    pub fn new(name: &'static str) -> Self {
        Self { window: None, title: name }
    }
}

impl Drop for Window {
    fn drop(&mut self) {
        // Might come in handy some time
    }
}
impl Deref for Window {
    type Target = Option<winit:🪟:Window>;

    fn deref(&self) -> &Self::Target {
        &self.window
    }
}


